contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(amount > 0, "amount must be positive");

        uint before = c.depositsCount();
        bool reverted;
        try c.receive{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.depositsCount() == before);
        } else {
            assert(c.depositsCount() == before + 1);
        }
    }
}

