    }

    receive() external payable {}

    function run() public payable {
        require(true);

        // ensure c has some balance (top-level call that changes c's state)
        c.sendMoney(address(this), 0);

        // record balance before the deciding call
        uint balBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
