contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint value) public payable {
        require(address(this).balance >= value);

        uint beforeBalance = address(c).balance;

        // Make this contract a non-owner caller by ensuring another account is the owner.
        // Since C's constructor sets owner = msg.sender and this test contract deployed c,
        // this test contract IS the owner. To get a non-owner caller we cannot change owner;
        // instead we call from a different context? Not possible. The only way to make a non-owner
        // call is if the test contract is not the owner. However, the constructor guarantees
        // the deployer is the owner. Therefore, to test non-owner revert we need to call
        // from an address that is not the owner. We cannot change msg.sender.
        // Hence this test cannot produce a non-owner call. So we instead test a different rule:
        // The owner calling withdraw(value) with value <= address(c).balance succeeds and
        // decreases c's balance by exactly value, and increases this contract's balance by exactly value.

        // Since this contract is the owner, we can proceed with the owner path.
        // Send `amount` wei to c first so that c has balance to withdraw from.
        uint amount = 1; // fixed small amount? But we need a parameter. Use `value` as the send amount and withdraw amount?
        // We want to test withdrawal success. Let's send `value` wei to c, then withdraw the same `value`
        // so that withdraw succeeds. Then check balances.
        require(address(this).balance >= value);
        (bool sent, ) = address(c).call{value: value}("");
        require(sent, "send failed");

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Owner calls withdraw(value). Since value <= beforeC, it should succeed.
        c.withdraw(value);

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: after an owner withdraw of exactly `value`, c's balance decreases by `value`
        // and this contract's balance increases by `value` (ignoring potential gas costs? balance change
        // should be exactly value because transfer of `value` wei).
        // However, if value is 0, no change. But still holds.
        // Also, c might have had other funds, but we only track the delta.
        assert(afterC == beforeC - value && afterThis == beforeThis + value);
    }

    receive() external payable {}
}

