        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        assert(reverted == (value > beforeBalance) && afterBalance == beforeBalance);
    }
}
